package vn.iotstar.controller.admin;
import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import vn.iotstar.entity.User;import vn.iotstar.service.*;import vn.iotstar.service.impl.*;import java.io.IOException;
@WebServlet("/admin/account/edit") public class AccountEditController extends HttpServlet{private final UserService s=new UserServiceImpl();protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{if(!AdminAuth.requireAdmin(r,p))return;User u=s.findById(Integer.parseInt(r.getParameter("id")));if(u==null){p.sendError(404);return;}r.setAttribute("account",u);r.getRequestDispatcher("/views/admin/edit-account.jsp").forward(r,p);}protected void doPost(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{if(!AdminAuth.requireAdmin(r,p))return;r.setCharacterEncoding("UTF-8");try{User u=s.findById(Integer.parseInt(r.getParameter("id")));if(u==null){p.sendError(404);return;}u.setEmail(r.getParameter("email"));u.setUserName(r.getParameter("username"));u.setFullName(r.getParameter("fullname"));String pw=r.getParameter("password");if(pw!=null&&!pw.isBlank())u.setPassWord(pw);u.setPhone(r.getParameter("phone"));u.setRoleid(Integer.parseInt(r.getParameter("roleid")));s.update(u);p.sendRedirect(r.getContextPath()+"/admin/account/list");}catch(Exception e){r.setAttribute("error",e.getMessage());doGet(r,p);}}}
